import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry matvec_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .pred %p<10>;
    .reg .f32  %f<10>;
    .reg .b32  %r<20>;
    .reg .b64  %rd<30>;

    .shared .align 4 .f32 sdata[256];

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [M];
    ld.param.u32 %r2,  [K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r3, %ctaid.x;   // row index
    mov.u32 %r4, %tid.x;     // thread index
    mov.u32 %r5, %ntid.x;    // block dim

    // bounds check on row (partial-grid safety)
    setp.ge.u32 %p1, %r3, %r1;
    @%p1 bra DONE;

    // row * K (64-bit)
    mul.wide.u32 %rd4, %r3, %r2;

    // accumulator
    mov.f32 %f1, 0f00000000;
    mov.u32 %r6, %r4;   // idx = tid

LOOP:
    setp.ge.u32 %p2, %r6, %r2;
    @%p2 bra LOOP_END;

    cvt.u64.u32 %rd5, %r6;
    add.u64 %rd6, %rd4, %rd5;      // row*K + idx
    shl.b64 %rd7, %rd6, 2;
    add.u64 %rd8, %rd1, %rd7;
    ld.global.f32 %f2, [%rd8];     // A[row,idx]

    cvt.u64.u32 %rd9, %r6;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd2, %rd10;
    ld.global.f32 %f3, [%rd11];    // B[idx]

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.u32 %r6, %r6, %r5;
    bra LOOP;

LOOP_END:
    mov.u32 %r7, %tid.x;
    mul.wide.u32 %rd12, %r7, 4;
    mov.u64 %rd13, sdata;
    add.u64 %rd14, %rd13, %rd12;
    st.shared.f32 [%rd14], %f1;

    bar.sync 0;

    mov.u32 %r8, 128;

RED_LOOP:
    setp.eq.u32 %p3, %r8, 0;
    @%p3 bra RED_DONE;

    setp.ge.u32 %p4, %r7, %r8;
    @%p4 bra RED_SKIP;

    mul.wide.u32 %rd15, %r7, 4;
    add.u64 %rd16, %rd13, %rd15;
    ld.shared.f32 %f4, [%rd16];

    add.u32 %r9, %r7, %r8;
    mul.wide.u32 %rd17, %r9, 4;
    add.u64 %rd18, %rd13, %rd17;
    ld.shared.f32 %f5, [%rd18];

    add.f32 %f6, %f4, %f5;
    st.shared.f32 [%rd16], %f6;

RED_SKIP:
    bar.sync 0;
    shr.u32 %r8, %r8, 1;
    bra RED_LOOP;

RED_DONE:
    setp.ne.u32 %p5, %r7, 0;
    @%p5 bra DONE;

    ld.shared.f32 %f7, [%rd13];

    cvt.u64.u32 %rd19, %r3;
    shl.b64 %rd20, %rd19, 2;
    add.u64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f7;

DONE:
    ret;
}
"""

_ptx_module = None


def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_kernel")


class ModelNew(nn.Module):
    """
    Simple model that performs matrix-vector multiplication (C = A * B)
    using a custom PTX kernel.
    """

    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32

        A = A.contiguous()
        B = B.contiguous()

        M, K = A.shape[0], A.shape[1]

        C = torch.empty((M, 1), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x = 256
        grid_x = M

        module.launch(
            "matvec_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

